import { atom, read, update } from 'claude-code'
import type { Register } from 'claude-code'

import type { Snap, Tok } from '../types'
import { pickLang, settingFrom, type Lang } from './lang'
import { TEXT } from './text'
import { divider, pack, rows, stack } from './tokens'

const snap = atom({ plugin: 'token-usage-panel', key: 'snap' } as const, null as Snap | null)
const tok = atom({ plugin: 'token-usage-panel', key: 'tok' } as const, { ctx: null, model: '', cost: null, limits: [], lastAt: null, per: null, status: null, now: 0 } as Tok)
const lang = atom({ plugin: 'token-usage-panel', key: 'lang' } as const, null as Lang | null)
const W = 60
const k = (n: number) => (n >= 1e6 ? `${+(n / 1e6).toFixed(1)}M` : n >= 1e3 ? `${+(n / 1e3).toFixed(1)}k` : `${n}`)
const STATUS_URL = 'https://status.claude.com/api/v2/status.json'

// Inputs for pickLang: CLAUDE_PANELS_LANG, Claude Code's `language` setting, LC_ALL, LANG.
async function langOf($: any): Promise<Lang> {
  const panels = await $.env.get('CLAUDE_PANELS_LANG')
  if (panels?.trim()) return pickLang({ panels })
  let setting: string | undefined
  try {
    const row = (await $.config.list()).find((r: any) => r.key === 'language')
    if (typeof row?.value === 'string' && row.value) setting = row.value
  } catch {
    setting = undefined // no config API here: fall back to the file
  }
  if (!setting) {
    try {
      const dir = (await $.env.get('CLAUDE_CONFIG_DIR')) || `${(await $.env.get('HOME')) ?? ''}/.claude`
      setting = settingFrom(await $.fs.read(`${dir}/settings.json`))
    } catch {
      setting = undefined // no settings file
    }
  }
  return pickLang({ setting, lcAll: await $.env.get('LC_ALL'), lang: await $.env.get('LANG') })
}

async function refresh($: any) {
  const b = (await $.session.usage({ breakdown: 'summary' })).context.breakdown
  if (!b) return
  const segs = b.categories.filter((c: any) => c.kind !== 'deferred').map((c: any) => ({ name: c.name, tokens: c.tokens, color: c.color, kind: c.kind }))
  await update($, snap, () => ({ total: b.totalTokens, max: b.rawMaxTokens, percent: b.percentage, segs }))
}

// Context, cost, limits, model. With stamp, a cost increase marks the last reply time
// (context can move before any reply, so only a cost increase counts).
async function measure($: any, stamp: boolean) {
  const u = await $.session.usage()
  const model = await $.session.model()
  const now = await $.clock.now()
  await update($, tok, t => ({
    ...t,
    ctx: u.context.tokens ?? null,
    model,
    cost: u.cost?.usd ?? null,
    limits: u.rateLimits.map((l: any) => ({ kind: l.kind, percentUsed: l.percentUsed, resetsAt: l.resetsAt })),
    lastAt: stamp && (u.cost?.usd ?? 0) > (t.cost ?? 0) ? now : t.lastAt,
    now,
  }))
}

async function readStatus($: any) {
  let s: string | null = null
  try {
    const r = await $.http.fetch(STATUS_URL)
    if (r.ok) s = JSON.parse(r.text)?.status?.indicator ?? null
  } catch {
    s = null
  }
  await update($, tok, t => ({ ...t, status: s }))
}

const tick = async ($: any) => {
  const now = await $.clock.now()
  await update($, tok, t => ({ ...t, now }))
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    const lg = await langOf($)
    await update($, lang, () => lg)
    void refresh($)
    void measure($, false)
    void readStatus($)
    $.clock.every(60_000, () => void tick($))
    $.clock.every(5 * 60_000, () => void readStatus($))
    return next(e)
  })
  on('session.measure', async ($, e, next) => {
    const r = await next(e)
    if (e.changed.includes('context')) await refresh($)
    if (e.changed.some(c => c === 'cost' || c === 'context' || c === 'rateLimits')) await measure($, e.changed.includes('cost') || e.changed.includes('context'))
    return r
  })
  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    const s = await read($, snap)
    const t = await read($, tok)
    // decided at session.start; a render before that asks directly (drawing cannot write state)
    const x = TEXT[(await read($, lang)) ?? (await langOf($))]
    const { Box, Text } = $.ui.resolve(e)
    const rs = rows(t, t.now || Date.now(), x)
    const cols = e.props.bodyColumns || 80
    const bw = Math.max(10, Math.min(W, cols - 22))
    const tokens = (
      <Box flexDirection="column">
        <Text dimColor>{divider(cols, x)}</Text>
        {stack(rs, cols, x).map((r, i) => (
          <Text wrap="truncate" dimColor={i === 0 || r.left === x.all}>
            {r.left}
            {r.right ? <Text color={r.right.color}>{r.right.text}</Text> : ''}
          </Text>
        ))}
      </Box>
    )
    if (!s) return <Box flexDirection="column">{tokens}</Box>
    const used = s.segs.filter(x => x.kind !== 'free')
    const cells = used.map(x => ({ ...x, n: x.tokens > 0 ? Math.max(1, Math.round((x.tokens / s.max) * bw)) : 0 }))
    const legend = used.filter(c => c.tokens > 0)
    const rest = Math.max(0, bw - cells.reduce((a, c) => a + c.n, 0))
    return (
      <Box flexDirection="column">
        {tokens}
        <Text dimColor>{x.breakdown}</Text>
        <Text>
          {cells.map(c => <Text color={c.color}>{'█'.repeat(c.n)}</Text>)}
          <Text dimColor>{'░'.repeat(rest)}</Text>
          <Text> {k(s.total)}/{k(s.max)} ({s.percent}%)</Text>
        </Text>
        {pack(legend.map(c => `■ ${c.name} ${k(c.tokens)}`), cols).map(line => (
          <Text>{line.map((i, j) => <Text>{j ? '  ' : ''}<Text color={legend[i]!.color}>■</Text>{` ${legend[i]!.name} ${k(legend[i]!.tokens)}`}</Text>)}</Text>
        ))}
      </Box>
    )
  })
}

