// Picks the display language: en or ja. Pure; register.tsx gathers the inputs.

export type Lang = 'en' | 'ja'

export type LangInputs = { panels?: string; setting?: string; lcAll?: string; lang?: string }

const JA_SETTING = /^(ja\b|ja[-_]|japanese|日本語|nihongo)/i

/** 1. CLAUDE_PANELS_LANG, 2. Claude Code's `language` setting, 3. LC_ALL / LANG, 4. en. */
export function pickLang({ panels, setting, lcAll, lang }: LangInputs): Lang {
  const p = panels?.trim().toLowerCase()
  if (p) return p === 'ja' ? 'ja' : 'en'
  if (setting && JA_SETTING.test(setting.trim())) return 'ja'
  const loc = lcAll || lang
  if (loc && /^ja/i.test(loc)) return 'ja'
  return 'en'
}

/** The `language` value from a settings.json text; undefined when absent or not JSON. */
export function settingFrom(json: string): string | undefined {
  try {
    const v = JSON.parse(json)?.language
    return typeof v === 'string' ? v : undefined
  } catch {
    return undefined // not JSON
  }
}

