// Cost math and formatting for the token usage panel. Pure functions.
import type { Limit, Tok } from '../types'
import { TEXT, type Text } from './text'

// Input price in $ per 1M tokens.
export function inputRate(model: string): number {
  if (model.includes('fable') || model.includes('mythos')) return 10
  if (model.includes('opus')) {
    if (model.includes('opus-4-1') || model.includes('opus-4-0')) return 15
    if (/opus-4(-|$)/.test(model)) return 15
    return 5
  }
  if (model.includes('sonnet')) return model.includes('sonnet-5') ? 2 : 3
  if (model.includes('haiku')) return model.includes('haiku-3') ? 0.8 : 1
  return 5
}

// Cache-read multiplier.
export function readFactor(model: string): number {
  return model.includes('fable-5-1') || model.includes('mythos-5-1') ? 0.025 : 0.1
}

export const TTL_MS = 60 * 60 * 1000

export const money = (d: number) => (d >= 10 ? `$${d.toFixed(1)}` : `$${d.toFixed(2)}`)

export function amount(d: number, digits: number, per: number | null): string {
  return per ? `${(d / per).toFixed(digits)}% (${money(d)})` : money(d)
}

export const pct = (d: number, per: number | null) => (per ? `${(d / per).toFixed(3)}%` : money(d))

export function cacheText(lastAt: number | null, now: number, s: Text = TEXT.en): string {
  if (lastAt == null) return '—'
  const left = TTL_MS - (now - lastAt)
  if (left <= 0) return s.expired
  return s.minLeft(Math.ceil(left / 60000))
}

const p2 = (n: number) => String(n).padStart(2, '0')

// 5-hour limit: reset time, HH:mm today or M/d HH:mm otherwise
export function resetClock(at: number, now: number): string {
  const a = new Date(at)
  const n = new Date(now)
  const hm = `${p2(a.getHours())}:${p2(a.getMinutes())}`
  const same = a.getFullYear() === n.getFullYear() && a.getMonth() === n.getMonth() && a.getDate() === n.getDate()
  return same ? hm : `${a.getMonth() + 1}/${a.getDate()} ${hm}`
}

// Weekly limit: time left as XdYh / Yh / Zm
export function remain(ms: number): string {
  const m = Math.max(0, Math.floor(ms / 60000))
  const d = Math.floor(m / 1440)
  const h = Math.floor((m % 1440) / 60)
  if (d > 0) return `${d}d${h}h`
  if (h > 0) return `${h}h`
  return `${m}m`
}

const resetAt = (l: Limit) => (l.resetsAt ? Date.parse(l.resetsAt) : NaN)

export function limitText(l: Limit | undefined, now: number, kind: 'five_hour' | 'seven_day'): string {
  if (!l) return '—'
  const at = resetAt(l)
  if (Number.isFinite(at) && at <= now) return '—'
  const p = `${Math.round(l.percentUsed)}%`
  if (!Number.isFinite(at)) return p
  return `${p} (${kind === 'five_hour' ? resetClock(at, now) : remain(at - now)})`
}

export function level(l: Limit | undefined, now: number): 'red' | 'yellow' | undefined {
  if (!l) return undefined
  const at = resetAt(l)
  if (Number.isFinite(at) && at <= now) return undefined
  return l.percentUsed >= 90 ? 'red' : l.percentUsed >= 75 ? 'yellow' : undefined
}

// Display width: East Asian wide chars take 2 columns, symbols like — and ■ take 1
const wide = (c: number) =>
  (c >= 0x1100 && c <= 0x115f) || (c >= 0x2e80 && c <= 0xa4cf) || (c >= 0xac00 && c <= 0xd7a3) || (c >= 0xf900 && c <= 0xfaff) ||
  (c >= 0xfe30 && c <= 0xfe4f) || (c >= 0xff00 && c <= 0xff60) || (c >= 0xffe0 && c <= 0xffe6) || c >= 0x20000
export function width(s: string): number {
  let w = 0
  for (const ch of s) w += wide(ch.codePointAt(0) ?? 0) ? 2 : 1
  return w
}
export const pad = (s: string, w: number) => s + ' '.repeat(Math.max(0, w - width(s)))

export type Cell = { text: string; color?: 'red' | 'yellow' }
export type Row = { left: string; right: Cell | null }

export const COL = 46
const lw = (s: Text) => Math.max(...s.left.map(width)) + 1
const rw = (s: Text) => Math.max(...s.right.map(width))

export const header = (s: Text = TEXT.en) => `${pad(s.session, COL)}${s.all}`

// Four rows: left = this session, right = account-wide limits
export function rows(t: Tok, now: number, s: Text = TEXT.en): Row[] {
  const ctx = t.ctx
  const rate = inputRate(t.model)
  const base = ctx == null ? '—' : amount((ctx * rate * readFactor(t.model)) / 1e6, 4, t.per)
  const cold = ctx == null ? '—' : `${pct((ctx * rate * 2.0) / 1e6, t.per)})`
  const total = t.cost == null ? '—' : amount(t.cost, 3, t.per)
  const five = t.limits.find(l => l.kind === 'five_hour')
  const week = t.limits.find(l => l.kind === 'seven_day')
  const status: Cell = t.status == null ? { text: '—' } : t.status === 'none' ? { text: s.ok } : { text: s.degraded, color: 'yellow' }
  const RW = rw(s), LW = lw(s)
  const right = (label: string, c: Cell): Cell => ({ text: `${pad(label, RW)}: ${c.text}`, color: c.color })
  const left = (i: number, v: string) => pad(`${pad(s.left[i]!, LW)}: ${v}`, COL)
  return [
    { left: left(0, base), right: right(s.right[0], { text: limitText(five, now, 'five_hour'), color: level(five, now) }) },
    { left: left(1, cold), right: right(s.right[1], { text: limitText(week, now, 'seven_day'), color: level(week, now) }) },
    { left: left(2, total), right: null },
    { left: left(3, cacheText(t.lastAt, now, s)), right: right(s.right[2], status) },
  ]
}

// Title rule centered to the exact width; drops ornaments when narrow
export function divider(cols: number, s: Text = TEXT.en): string {
  const TITLE = s.title
  for (const mid of [` ⋆ ✦ ${TITLE} ✦ ⋆ `, ` ✦ ${TITLE} ✦ `, TITLE]) {
    const rest = cols - width(mid)
    if (rest < 0) continue
    const fill = (n: number, from: number) => Array.from({ length: n }, (_, i) => ((i + from) % 2 ? '·' : '─')).join('')
    const l = Math.floor(rest / 2)
    return fill(l, 0) + mid + fill(rest - l, l + width(mid))
  }
  return TITLE
}

// Below this width the right column moves under the left one
export const sideMin = (s: Text = TEXT.en) => COL + rw(s) + 2 + 14
export function stack(rs: Row[], cols: number, s: Text = TEXT.en): { left: string; right: Cell | null }[] {
  if (cols >= sideMin(s)) return [{ left: header(s), right: null }, ...rs]
  return [
    { left: s.session, right: null }, ...rs.map(r => ({ left: r.left.trimEnd(), right: null })),
    { left: s.all, right: null }, ...rs.filter(r => r.right).map(r => ({ left: '', right: r.right })),
  ]
}

// Pack legend items into lines that fit; never split an item
export function pack(items: string[], cols: number, gap = 2): number[][] {
  const lines: number[][] = []
  let cur: number[] = [], used = 0
  items.forEach((s, i) => {
    const w = width(s)
    if (cur.length && used + gap + w > cols) { lines.push(cur); cur = []; used = 0 }
    used += (cur.length ? gap : 0) + w
    cur.push(i)
  })
  if (cur.length) lines.push(cur)
  return lines
}

