export type Seg = { name: string; tokens: number; color: string; kind: string }
export type Snap = { total: number; max: number; percent: number; segs: Seg[] }
export type Limit = { kind: string; percentUsed: number; resetsAt?: string }
// Panel values; null when unknown
export type Tok = {
  ctx: number | null
  model: string
  cost: number | null
  limits: Limit[]
  lastAt: number | null
  per: number | null
  status: string | null
  now: number
}

declare module 'claude-code' {
  interface PluginState {
    'token-usage-panel': { snap: Snap | null; tok: Tok; lang: 'en' | 'ja' | null }
  }
}
